import ArgumentParser
import Foundation

@main
struct ReleaseNotes: ParsableCommand {
    static let configuration = CommandConfiguration(
        abstract: "Collects merged PR titles since a tag and prints release notes."
    )

    @Argument(help: "The git tag to start from, e.g. v2.3.0")
    var sinceTag: String

    @Flag(help: "Group entries by conventional-commit type.")
    var grouped = false

    func run() throws {
        let mergeLog = try shell("git", "log", "\(sinceTag)..HEAD", "--merges", "--pretty=%s")
        let titles = mergeLog.split(separator: "\n").map(String.init).filter { !$0.isEmpty }

        guard !titles.isEmpty else {
            print("No merged pull requests since \(sinceTag).")
            return
        }

        if grouped {
            let byType = Dictionary(grouping: titles) { title in
                title.split(separator: ":").first.map(String.init) ?? "other"
            }
            for (type, entries) in byType.sorted(by: { $0.key < $1.key }) {
                print("## \(type)")
                entries.forEach { print("- \($0)") }
                print("")
            }
        } else {
            titles.forEach { print("- \($0)") }
        }
    }

    private func shell(_ arguments: String...) throws -> String {
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        process.arguments = arguments
        let pipe = Pipe()
        process.standardOutput = pipe
        try process.run()
        process.waitUntilExit()
        let output = pipe.fileHandleForReading.readDataToEndOfFile()
        return String(decoding: output, as: UTF8.self)
    }
}

