import Foundation
import os

actor UploadQueue {
    struct PendingUpload: Codable, Hashable {
        let localID: UUID
        let fileURL: URL
        var attempts: Int
    }

    private let maxAttempts: Int
    private let uploader: PhotoUploading
    private let logger = Logger(subsystem: "com.example.photos", category: "UploadQueue")
    private var pending: [PendingUpload] = []
    private var isDraining = false

    init(uploader: PhotoUploading, maxAttempts: Int = 5) {
        self.uploader = uploader
        self.maxAttempts = maxAttempts
    }

    func enqueue(_ fileURL: URL) {
        pending.append(PendingUpload(localID: UUID(), fileURL: fileURL, attempts: 0))
    }

    func drain() async {
        guard !isDraining else { return }
        isDraining = true
        defer { isDraining = false }

        while !pending.isEmpty {
            var upload = pending.removeFirst()
            do {
                try await uploader.upload(fileAt: upload.fileURL, id: upload.localID)
            } catch {
                upload.attempts += 1
                logger.error("upload \(upload.localID) failed (attempt \(upload.attempts)): \(error.localizedDescription)")
                if upload.attempts < maxAttempts {
                    pending.append(upload)
                }
            }
        }
    }
}

