import Foundation

struct ContactRow {
    let name: String
    let email: String
    let phone: String?
}

enum CSVImportError: Error {
    case emptyFile
    case missingColumn(String)
}

func doStuff(_ contents: String) throws -> [ContactRow] {
    let lines = contents.split(whereSeparator: \.isNewline).map(String.init)
    guard let headerLine = lines.first else { throw CSVImportError.emptyFile }
    let columns = headerLine.split(separator: ",").map { $0.trimmingCharacters(in: .whitespaces).lowercased() }
    guard let nameIndex = columns.firstIndex(of: "name") else { throw CSVImportError.missingColumn("name") }
    guard let emailIndex = columns.firstIndex(of: "email") else { throw CSVImportError.missingColumn("email") }
    let phoneIndex = columns.firstIndex(of: "phone")

    var temp: [ContactRow] = []
    for line in lines.dropFirst() {
        let fields = line.split(separator: ",", omittingEmptySubsequences: false).map(String.init)
        guard fields.count > max(nameIndex, emailIndex) else { continue }
        let phone = phoneIndex.flatMap { fields.indices.contains($0) ? fields[$0] : nil }
        temp.append(ContactRow(name: fields[nameIndex], email: fields[emailIndex], phone: phone))
    }
    return temp
}

