import Foundation
import os

protocol NotesRemote: Sendable {
    func fetchChanges(since cursor: String?) async throws -> RemoteChangeSet
    func push(_ notes: [NoteRecord]) async throws -> [NoteRecord.ID: Date]
}

protocol NotesLocalStore: Sendable {
    func pendingLocalChanges() async throws -> [NoteRecord]
    func apply(_ remote: [NoteRecord]) async throws
    func markSynced(_ acknowledgements: [NoteRecord.ID: Date]) async throws
    func delete(ids: [NoteRecord.ID]) async throws
    func loadCursor() async -> String?
    func saveCursor(_ cursor: String?) async
}

struct NoteRecord: Codable, Identifiable, Sendable, Equatable {
    let id: UUID
    var title: String
    var body: String
    var modifiedAt: Date
    var isDeleted: Bool
}

struct RemoteChangeSet: Sendable {
    let upserts: [NoteRecord]
    let deletions: [NoteRecord.ID]
    let nextCursor: String?
    let hasMore: Bool
}

enum SyncOutcome: Equatable {
    case skipped
    case completed(pulled: Int, pushed: Int, deleted: Int)
    case failed(String)
}

actor NotesSyncEngine {
    private let remote: NotesRemote
    private let store: NotesLocalStore
    private let logger = Logger(subsystem: "com.example.notes", category: "Sync")
    private let maxPullPages: Int
    private var isSyncing = false
    private var lastOutcome: SyncOutcome = .skipped

    init(remote: NotesRemote, store: NotesLocalStore, maxPullPages: Int = 20) {
        self.remote = remote
        self.store = store
        self.maxPullPages = maxPullPages
    }

    var latestOutcome: SyncOutcome { lastOutcome }

    func sync() async -> SyncOutcome {
        guard !isSyncing else {
            logger.debug("sync requested while already running; ignoring")
            return .skipped
        }
        isSyncing = true
        defer { isSyncing = false }

        do {
            let pushed = try await pushLocalChanges()
            let (pulled, deleted) = try await pullRemoteChanges()
            let outcome = SyncOutcome.completed(pulled: pulled, pushed: pushed, deleted: deleted)
            lastOutcome = outcome
            logger.info("sync finished: pulled \(pulled), pushed \(pushed), deleted \(deleted)")
            return outcome
        } catch is CancellationError {
            lastOutcome = .skipped
            return .skipped
        } catch {
            logger.error("sync failed: \(error.localizedDescription)")
            lastOutcome = .failed(error.localizedDescription)
            return lastOutcome
        }
    }

    private func pushLocalChanges() async throws -> Int {
        let pendingNotes = try await store.pendingLocalChanges()
        guard !pendingNotes.isEmpty else { return 0 }
        let acknowledgements = try await remote.push(pendingNotes)
        let rejected = pendingNotes.filter { acknowledgements[$0.id] == nil }
        if !rejected.isEmpty {
            logger.warning("server did not acknowledge \(rejected.count) notes; they stay pending")
        }
        try await store.markSynced(acknowledgements)
        return acknowledgements.count
    }

    private func pullRemoteChanges() async throws -> (pulled: Int, deleted: Int) {
        var cursor = await store.loadCursor()
        var pulled = 0
        var deleted = 0
        var pagesFetched = 0

        repeat {
            try Task.checkCancellation()
            let changeSet = try await remote.fetchChanges(since: cursor)
            let localPending = try await store.pendingLocalChanges()
            let pendingByID = Dictionary(uniqueKeysWithValues: localPending.map { ($0.id, $0) })
            let accepted = changeSet.upserts.filter { remoteNote in
                guard let localNote = pendingByID[remoteNote.id] else { return true }
                return remoteNote.modifiedAt > localNote.modifiedAt
            }
            try await store.apply(accepted)
            try await store.delete(ids: changeSet.deletions)
            pulled += accepted.count
            deleted += changeSet.deletions.count
            cursor = changeSet.nextCursor
            await store.saveCursor(cursor)
            pagesFetched += 1
            if !changeSet.hasMore { break }
        } while pagesFetched < maxPullPages

        if pagesFetched == maxPullPages {
            logger.notice("stopped pulling after \(pagesFetched) pages; remaining changes sync next run")
        }
        return (pulled, deleted)
    }
}

extension NotesSyncEngine {
    static func conflictWinner(local: NoteRecord, remote: NoteRecord) -> NoteRecord {
        if local.isDeleted != remote.isDeleted {
            return local.isDeleted ? local : remote
        }
        return local.modifiedAt >= remote.modifiedAt ? local : remote
    }
}

import Foundation
import HealthKit
import os

struct ImportedWorkout: Codable, Identifiable {
    let id: UUID
    let activity: String
    let start: Date
    let end: Date
    let activeEnergyKilocalories: Double
    let distanceMeters: Double?
    let averageHeartRate: Double?
}

final class WorkoutImporter {
    private let healthStore = HKHealthStore()
    private let logger = Logger(subsystem: "com.example.fitlog", category: "WorkoutImporter")
    private let calendar = Calendar(identifier: .gregorian)

    func requestAuthorization() async throws {
        let readTypes: Set<HKObjectType> = [
            HKObjectType.workoutType(),
            HKQuantityType(.activeEnergyBurned),
            HKQuantityType(.distanceWalkingRunning),
            HKQuantityType(.heartRate),
        ]
        try await healthStore.requestAuthorization(toShare: [], read: readTypes)
    }

    func importRecentWorkouts(now: Date = Date()) async throws -> [ImportedWorkout] {
        let windowStart = calendar.date(byAdding: .day, value: -45, to: now)!
        let predicate = HKQuery.predicateForSamples(withStart: windowStart, end: now)
        let descriptor = HKSampleQueryDescriptor(
            predicates: [.workout(predicate)],
            sortDescriptors: [SortDescriptor(\.startDate, order: .reverse)],
            limit: 500
        )
        let workouts = try await descriptor.result(for: healthStore)
        print("fetched workouts", workouts.count, workouts.first as Any)

        var imported: [ImportedWorkout] = []
        for workout in workouts {
            guard workout.duration > 300 else { continue }
            let heartRate = try await averageHeartRate(during: workout)
            imported.append(
                ImportedWorkout(
                    id: workout.uuid,
                    activity: activityName(for: workout.workoutActivityType),
                    start: workout.startDate,
                    end: workout.endDate,
                    activeEnergyKilocalories: workout.statistics(for: HKQuantityType(.activeEnergyBurned))?
                        .sumQuantity()?.doubleValue(for: .kilocalorie()) ?? 0,
                    distanceMeters: workout.statistics(for: HKQuantityType(.distanceWalkingRunning))?
                        .sumQuantity()?.doubleValue(for: .meter()),
                    averageHeartRate: heartRate
                )
            )
        }
        logger.info("imported \(imported.count) workouts")
        return imported
    }

    private func averageHeartRate(during workout: HKWorkout) async throws -> Double? {
        let heartRateType = HKQuantityType(.heartRate)
        let predicate = HKQuery.predicateForSamples(withStart: workout.startDate, end: workout.endDate)
        let descriptor = HKStatisticsQueryDescriptor(
            predicate: .quantitySample(type: heartRateType, predicate: predicate),
            options: .discreteAverage
        )
        let statistics = try await descriptor.result(for: healthStore)
        let beatsPerMinute = HKUnit.count().unitDivided(by: .minute())
        return statistics?.averageQuantity()?.doubleValue(for: beatsPerMinute)
    }

    private func activityName(for activityType: HKWorkoutActivityType) -> String {
        switch activityType {
        case .running: return "Run"
        case .walking: return "Walk"
        case .cycling: return "Ride"
        case .swimming: return "Swim"
        case .traditionalStrengthTraining, .functionalStrengthTraining: return "Strength"
        case .yoga: return "Yoga"
        // TODO: map the remaining activity types
        default: return "Workout"
        }
    }

    func export(_ workouts: [ImportedWorkout], to directory: URL) throws -> URL {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
        let encoded = try encoder.encode(workouts)
        let timestamp = ISO8601DateFormatter().string(from: Date())
        let fileURL = directory.appendingPathComponent("workouts-\(timestamp).json")
        try encoded.write(to: fileURL, options: .atomic)
        return fileURL
    }
}

