        }
        spinner.startAnimating()
        scanButton.isEnabled = false

        recognitionQueue.async {
            let request = VNRecognizeTextRequest()
            request.recognitionLevel = .accurate
            let handler = VNImageRequestHandler(cgImage: cgImage)
            do {
                try handler.perform([request])
            } catch {
                self.logger.error("text recognition failed: \(error.localizedDescription)")
            }
            let lines = (request.results ?? []).compactMap { $0.topCandidates(1).first?.string }
            let total = ReceiptTotalParser.total(in: lines)
            self.spinner.stopAnimating()
            self.scanButton.isEnabled = true
            self.totalLabel.text = total.map { "Total: \($0)" } ?? "Couldn't find a total."
        }
    }
}

enum ReceiptTotalParser {
    private static let totalKeywords = ["total", "amount due", "balance due"]

    static func total(in lines: [String]) -> String? {
        let candidates = lines.filter { line in
            let lowered = line.lowercased()
            return totalKeywords.contains { lowered.contains($0) }
        }
        return candidates.last.flatMap(Self.amount(in:))
    }

    private static func amount(in line: String) -> String? {
        guard let range = line.range(of: #"\d+[.,]\d{2}"#, options: .regularExpression) else { return nil }
        return String(line[range])
    }
}

