import BackgroundTasks
import os

enum BackgroundRefresh {
    static let taskIdentifier = "com.example.news.refresh"
    private static let logger = Logger(subsystem: "com.example.news", category: "BackgroundRefresh")
    private static let refreshInterval: TimeInterval = 60 * 60 * 4

    static func register(feedStore: FeedStore) {
        BGTaskScheduler.shared.register(forTaskWithIdentifier: taskIdentifier, using: nil) { task in
            guard let refreshTask = task as? BGAppRefreshTask else {
                task.setTaskCompleted(success: false)
                return
            }
            handle(refreshTask, feedStore: feedStore)
        }
    }

    static func schedule() {
        let request = BGAppRefreshTaskRequest(identifier: taskIdentifier)
        request.earliestBeginDate = Date(timeIntervalSinceNow: refreshInterval)
        do {
            try BGTaskScheduler.shared.submit(request)
        } catch {
            logger.error("could not schedule refresh: \(error.localizedDescription)")
        }
    }

    private static func handle(_ refreshTask: BGAppRefreshTask, feedStore: FeedStore) {
        // Reschedule before doing any work so the refresh chain survives even if
        // the system expires this run early.
        schedule()
        let refreshWork = Task {
            do {
                let newCount = try await feedStore.refresh()
                logger.info("background refresh fetched \(newCount) stories")
                refreshTask.setTaskCompleted(success: true)
            } catch {
                logger.error("background refresh failed: \(error.localizedDescription)")
                refreshTask.setTaskCompleted(success: false)
            }
        }
        refreshTask.expirationHandler = { refreshWork.cancel() }
    }
}

import UserNotifications

enum ReminderError: Error {
    case notAuthorized
}

struct ReminderScheduler {
    let center: UNUserNotificationCenter

    func scheduleReminder(for habit: Habit) async throws {
        let content = UNMutableNotificationContent()
        content.title = habit.name
        content.body = habit.reminderMessage
        // Use the habit ID as the request identifier so rescheduling replaces the
        // pending reminder instead of stacking duplicates.
        let request = UNNotificationRequest(
            identifier: habit.id.uuidString,
            content: content,
            trigger: UNCalendarNotificationTrigger(dateMatching: habit.reminderTime, repeats: true)
        )
        // Notification center silently drops requests while authorization is
        // .notDetermined, so surface that to the caller instead.
        let settings = await center.notificationSettings()
        guard settings.authorizationStatus == .authorized else {
            throw ReminderError.notAuthorized
        }
        try await center.add(request)
    }
}

